import React, { useState } from "react";
import { useAuthController } from "../controllers/AuthController";
import { Link } from "react-router-dom";
import "../styles/signup.css"; // Using the same styles as SignupView for consistency

const LoginView = () => {
  const { loginWithEmail } = useAuthController();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [errorMsg, setErrorMsg] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await loginWithEmail(email, password);
      // On success, redirect logic should be handled elsewhere
    } catch (error) {
      setErrorMsg(error.message);
    }
  };

  return (
    <div className="auth-container">
      <div className="auth-card">
        <h2 className="auth-title">Login</h2>
        <form onSubmit={handleSubmit} className="auth-form">
          <div className="input-group">
            <label>Email Address</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          <div className="input-group">
            <label>Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          {errorMsg && <p className="error-message">{errorMsg}</p>}

          <button type="submit" className="auth-button">Login</button>
        </form>

        <p className="auth-footer">
          Don't Have An Account? <Link to="/signup" className="auth-link">Register Here</Link>
        </p>
      </div>
    </div>
  );
};

export default LoginView;
